    this.input.setSensitivity(this.settings.sens);
    this.missions = new Missions(this);
    this.ui = new UI(this);
    this.ui.setQualityUI(qName);
    this.ui.setBond(this.state.bond);
    this.ui.updateArtifacts();
    this.ui.updateMoney();
