    this.grade.uniforms.uTexel.value.set(1 / innerWidth, 1 / innerHeight);
    this.grade.uniforms.uFxaa.value = this.quality.level === "low" ? 0 : 1;
    this.grade.uniforms.uGrain.value = this.quality.level === "low" ? 0.01 : 0.016;
