    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.1;
    grp.add(ring);
    const beam = new Mesh(new CylinderGeometry(0.35, 0.9, 40, 8, 1, true), new MeshBasicMaterial({ color: 5108735, transparent: true, opacity: 0.055, side: DoubleSide, blending: AdditiveBlending, depthWrite: false, toneMapped: false }));
    beam.position.y = 20;
    grp.add(beam);
    const gem = new Mesh(new OctahedronGeometry(0.7), new MeshBasicMaterial({ color: 5108735, transparent: true, opacity: 0.9, toneMapped: false }));
    gem.position.y = 5;
    grp.add(gem);
